Given a Binary Search Tree, the task is to find the node with the maximum value in a BST.Example:Input:Output : 7Input:Output: 20Table of Content[Naive Approach] Using Inorder Traversal – O(n) Time and O(n) Space[Expected Approach] Iterative Approach – O(n) Time and O(1) Space[Naive Approach] Using Inorder Traversal – O(n) Time and O(n) SpaceThe idea is to use the property of BST which says inorder traversal of a binary search tree always returns the value of nodes in sorted order. So the last value in the sorted vector will be the maximumvalue which is the answer. Below is the implementation of the above approach:
            C++

    #include <iostream>
#include <vector>
using namespace std;

class Node {
public:
    int data;
    Node* left;
    Node* right;
    Node(int val) : data(val), left(nullptr), right(nullptr) {}
};

void inorder(Node* root, vector<int>& sorted_inorder) {

    if (root == nullptr) return;

    // Traverse left subtree
    inorder(root->left, sorted_inorder);

    // Store the current node's data
    sorted_inorder.push_back(root->data);

    // Traverse right subtree
    inorder(root->right, sorted_inorder);
}

int maxValue(Node* root) {
    if (root == nullptr) return -1;

    // Using a vector to hold inorder elements
    vector<int> sorted_inorder;

    // Call the recursive inorder function
    inorder(root, sorted_inorder);

    // Return the last element, which is the maximum
    return sorted_inorder.back();
}

int main() {
    // Representation of input binary search tree
    //        5
    //       / \
    //      4   6
    //     /     \
    //    3       7
    //   /  
    //  1
    Node* root = new Node(5);
    root->left = new Node(4);
    root->right = new Node(6);
    root->left->left = new Node(3);
    root->right->right = new Node(7);
    root->left->left->left = new Node(1);

    cout << maxValue(root) << endl;
    return 0;
}


