        tree.root.left = new Node(4);
        tree.root.right = new Node(6);
        tree.root.left.left = new Node(3);
        tree.root.right.right = new Node(7);
        tree.root.left.left.left = new Node(1);

        System.out.println(tree.maxValue(tree.root));
    }
}


